/**
* Normalizes Arabic text for flexible and intelligent searching.
* Removes diacritics (tashkeel), unifies alef/yaa/taa marbuta variants.
*/
function normalizeArabic(text) {
	if (!text) return "";
	return text.toLowerCase().replace(/[\u064B-\u065F\u0670]/g, "").replace(/[أإآٱ]/g, "ا").replace(/ى/g, "ي").replace(/ة/g, "ه").replace(/ك/g, "ك").replace(/ؤ/g, "و").replace(/ئ/g, "ي").trim();
}
